const DrawingPreview: React.FC<{ tool: ToolType; points: IPoint[]; cursorPos: THREE.Vector3 }> = ({ tool, points, cursorPos }) => {
    const currentPoint = cursorPos;
    if (points.length === 0) return null;
    const startPoint = points[0];

    if (tool === ToolType.DRAW_LINE) {
        // Line can be 3D
        const linePoints = points.map(p => new THREE.Vector3(p.x, p.y, p.z));
        linePoints.push(currentPoint);
        return <SimpleLine points={linePoints} color="black" dashed />;
    }

    // For 2D shapes, we project to the plane of the first point
    const drawingY = startPoint.y;
    const flatCurrent = new THREE.Vector3(currentPoint.x, drawingY, currentPoint.z);
    const startVec = new THREE.Vector3(startPoint.x, drawingY, startPoint.z);

    if (tool === ToolType.DRAW_RECT) {
        const p1 = startVec;
        const p2 = flatCurrent;

        const minX = Math.min(p1.x, p2.x);
        const maxX = Math.max(p1.x, p2.x);
        const minZ = Math.min(p1.z, p2.z);
        const maxZ = Math.max(p1.z, p2.z);

        const rectPoints = [
            new THREE.Vector3(minX, drawingY, minZ),
            new THREE.Vector3(maxX, drawingY, minZ),
            new THREE.Vector3(maxX, drawingY, maxZ),
            new THREE.Vector3(minX, drawingY, maxZ),
            new THREE.Vector3(minX, drawingY, minZ),
        ];

        return <SimpleLine points={rectPoints} color="black" dashed />;
    }

    if (tool === ToolType.DRAW_CIRCLE) {
        const radius = startVec.distanceTo(flatCurrent);
        if (radius < 0.01) return null;
        const circlePoints = createCirclePoints(radius).map(p => new THREE.Vector3(p.x + startPoint.x, drawingY, p.z + startPoint.z));
        return (
            <>
                <SimpleLine points={circlePoints} color="black" dashed />
                <SimpleLine points={[startVec, flatCurrent]} color="gray" dashed opacity={0.5} />
            </>
        );
    }

    if (tool === ToolType.DRAW_ARC) {
        const radius = startVec.distanceTo(flatCurrent);
        if (radius < 0.01) return null;
        const arcPoints = createArcPoints(radius).map(p => new THREE.Vector3(p.x + startPoint.x, drawingY, p.z + startPoint.z));
         return (
            <>
                <SimpleLine points={arcPoints} color="black" dashed />
                <SimpleLine points={[startVec, flatCurrent]} color="gray" dashed opacity={0.5} />
            </>
        );
    }

    return null;
};

const InteractionLayer: React.FC<{
    shapes: IShape[];
    tool: ToolType;
    setCursorPos: (v: THREE.Vector3) => void;
    setSnapInfo: (s: SnapResult | null) => void;
    cursorPos: THREE.Vector3;
    snapInfo: SnapResult | null;
    drawPoints: IPoint[];
    isDragging: boolean;
    drawingHeight: number;
    typedInput: string;
}> = ({ shapes, tool, setCursorPos, setSnapInfo, cursorPos, snapInfo, drawPoints, isDragging, drawingHeight, typedInput }) => {
    const { setMeasurement, formatValue } = useApp();

    const updateMeasurement = useCallback((pos: THREE.Vector3, input?: string) => {
        let text = '';
        if (drawPoints.length > 0) {
            const start = drawPoints[drawPoints.length - 1]; // Last point
            const current = pos;

            // Calculate 3D distance
            const dist = Math.sqrt(
                (current.x - start.x)**2 + 
                (current.y - start.y)**2 + 
                (current.z - start.z)**2
            );

            if (tool === ToolType.DRAW_LINE) {
                text = `長度: ${input ? input : formatValue(dist)}`;
            } else if (tool === ToolType.DRAW_RECT) {
                if (input) {
                    text = `寬度, 深度: ${input}`;
                } else {
                    const w = Math.abs(current.x - start.x);
                    const d = Math.abs(current.z - start.z);
                    text = `寬度: ${formatValue(w)}, 深度: ${formatValue(d)}`;
                }
            } else if (tool === ToolType.DRAW_CIRCLE) {
                 text = `半徑: ${input ? input : formatValue(dist)}`;
            } else if (tool === ToolType.DRAW_ARC) {
                 text = `半徑: ${input ? input : formatValue(dist)}`;
            }
        } else {
             // Basic coordinate display when hovering
             if ([ToolType.DRAW_LINE, ToolType.DRAW_RECT, ToolType.DRAW_CIRCLE, ToolType.DRAW_ARC].includes(tool)) {
                 text = `起點: X ${formatValue(pos.x)}, Y ${formatValue(pos.y)}, Z ${formatValue(pos.z)}`;
             }
        }

        if (input !== undefined) {
             text += '|'; // Add cursor block
        }
        setMeasurement(text);
    }, [drawPoints, tool, formatValue, setMeasurement]);

    useEffect(() => {
        if (typedInput) updateMeasurement(cursorPos, typedInput);
    }, [typedInput, cursorPos, updateMeasurement]);

    useEffect(() => {
        if (!typedInput && snapInfo) updateMeasurement(snapInfo.position);
    }, [snapInfo, updateMeasurement, typedInput]);

    if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) return null;

    return (
        <group>
             {snapInfo && (
                <>
                    <SnapIndicator position={snapInfo.position} type={snapInfo.type} snapEdge={snapInfo.snapEdge} />
                    <CursorTooltip text={snapInfo.type === 'none' ? '' : snapInfo.type} position={snapInfo.position} type={snapInfo.type} />
                    <SurfaceGridHelper position={snapInfo.position} normal={snapInfo.normal} visible={snapInfo.type === 'face' || snapInfo.type === 'vertex'} />
                </>
             )}

             {drawPoints.length > 0 && (
                <DrawingPreview tool={tool} points={drawPoints} cursorPos={cursorPos} />
             )}
        </group>
    );
};

// --- Custom Hooks for Tool Managers ---

const usePushPullManager = () => {
    const { tool, shapes, updateShape, setMeasurement, formatValue } = useApp();
    const [ppState, setPPState] = useState<PushPullState>({
        mode: 'none',
        hoveredShapeId: null,
        hoveredEdgeIndex: -1,
        dragStartPoint: null,
        originalHeight: 0,
        originalPoints: [],
        normal: new THREE.Vector3(0, 1, 0)
    });
    const [isDragging, setIsDragging] = useState(false);
    const [tempShape, setTempShape] = useState<IShape | null>(null);

    const handlePointerMove = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.PUSH_PULL) return;

        if (isDragging && ppState.dragStartPoint && tempShape) {
            e.stopPropagation();
            const ray = e.ray;
            const normal = new THREE.Vector3(0, 0, 1).applyQuaternion(e.camera.quaternion);
            const planeNormal = new THREE.Vector3(normal.x, 0, normal.z).normalize();
            const plane = new THREE.Plane().setFromNormalAndCoplanarPoint(planeNormal, ppState.dragStartPoint);

            const target = new THREE.Vector3();
            ray.intersectPlane(plane, target);

            if (target) {
                const dy = target.y - ppState.dragStartPoint.y;
                let newHeight = Math.max(0.01, ppState.originalHeight + dy);
                newHeight = Math.round(newHeight / 0.05) * 0.05;

                setPPState(prev => ({ ...prev, dragHeight: newHeight }));
                setTempShape({ ...tempShape, height: newHeight });
                setMeasurement(`高度: ${formatValue(newHeight)}`);
            }
            return;
        }

        if (!isDragging) {
             const mesh = e.object as THREE.Mesh;
             if (!e.face) return;

             const normalMatrix = new THREE.Matrix3().getNormalMatrix(mesh.matrixWorld);
             const worldNormal = e.face.normal.clone().applyMatrix3(normalMatrix).normalize();

             if (worldNormal.y > 0.9) {
                 const shapeId = mesh.userData.id;
                 setPPState(prev => ({
                     ...prev,
                     mode: 'top',
                     hoveredShapeId: shapeId,
                     normal: worldNormal
                 }));
                 document.body.style.cursor = 'ns-resize';
             } else {
                 setPPState(prev => ({ ...prev, mode: 'none', hoveredShapeId: null }));
                 document.body.style.cursor = 'default';
             }
        }

    }, [tool, isDragging, ppState, tempShape, setMeasurement, formatValue]);

    const handlePointerDown = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.PUSH_PULL || ppState.mode !== 'top' || !ppState.hoveredShapeId) return;
        e.stopPropagation();

        const shape = shapes.find(s => s.id === ppState.hoveredShapeId);
        if (!shape) return;

        setIsDragging(true);
        setTempShape({ ...shape });
        setPPState(prev => ({
            ...prev,
            dragStartPoint: e.point.clone(),
            originalHeight: shape.height,
            dragHeight: shape.height
        }));
    }, [tool, ppState, shapes]);

    const handlePointerUp = useCallback(() => {
        if (!isDragging) return;

        if (tempShape && ppState.dragHeight !== undefined) {
             updateShape(tempShape.id, { height: ppState.dragHeight });
        }

        setIsDragging(false);
        setTempShape(null);
        setPPState(prev => ({ ...prev, dragStartPoint: null, dragHeight: undefined }));
        setMeasurement('');
    }, [isDragging, tempShape, ppState.dragHeight, updateShape, setMeasurement]);

    return {
        ppState,
        handlePointerMove,
        handlePointerDown,
        handlePointerUp,
        tempShape,
        isDragging
    };
};

const useDrawingManager = () => {
    const { tool, addShape, setMeasurement, formatValue, wallThickness } = useApp();
    const [drawPoints, setDrawPoints] = useState<IPoint[]>([]);
    const [cursorPos, setCursorPos] = useState(new THREE.Vector3());
    const [snapInfo, setSnapInfo] = useState<SnapResult | null>(null);
    const [typedInput, setTypedInput] = useState('');
    const [isDragging, setIsDragging] = useState(false);

    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) return;

            if (e.key === 'Backspace') {
                setTypedInput(prev => prev.slice(0, -1));
                return;
            }
            if (e.key === 'Enter') {
                handleInputCommit();
                return;
            }
            if (/^[0-9.]$/.test(e.key)) {
                setTypedInput(prev => prev + e.key);
            }
        };

        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [tool, typedInput]); 

    const createShape = useCallback((points: IPoint[], type: ToolType) => {
        // Calculate center for position
        let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity;
        points.forEach(p => {
            if(p.x < minX) minX = p.x;
            if(p.x > maxX) maxX = p.x;
            if(p.z < minZ) minZ = p.z;
            if(p.z > maxZ) maxZ = p.z;
        });
        const cx = (minX + maxX) / 2;
        const cz = (minZ + maxZ) / 2;
        const cy = points[0].y;

        // Relativize points
        const localPoints = points.map(p => ({ x: p.x - cx, y: 0, z: p.z - cz }));

        const newShape: IShape = {
            id: `shape-${Date.now()}`,
            type: 'solid', 
            name: type === ToolType.DRAW_RECT ? 'Room' : (type === ToolType.DRAW_CIRCLE ? 'Column' : 'Wall'),
            points: localPoints,
            height: DEFAULT_HEIGHT,
            color: DEFAULT_COLOR,
            position: [cx, cy, cz],
            rotation: 0,
            scale: [1, 1, 1]
        };
        addShape(newShape);
    }, [addShape]);

    const handleInputCommit = useCallback(() => {
        if (!typedInput) return;
        const val = parseFloat(typedInput);
        if (isNaN(val)) return;

        if (drawPoints.length > 0) {
            const start = drawPoints[drawPoints.length - 1];
            const direction = new THREE.Vector3(cursorPos.x - start.x, 0, cursorPos.z - start.z).normalize();
            if (direction.lengthSq() === 0) direction.set(1, 0, 0);

            const newPt = {
                x: start.x + direction.x * val,
                y: start.y, 
                z: start.z + direction.z * val
            };

            // For simplicity in this fix, we just add the point.
            // Complex shape finishing logic would go here.
        }
        setTypedInput('');
    }, [typedInput, drawPoints, cursorPos]);

    const handleClick = useCallback((e: ThreeEvent<MouseEvent>) => {
        const pt = snapInfo ? snapInfo.position : e.point;
        if (!pt) return;

        const newPoint: IPoint = { x: pt.x, y: pt.y, z: pt.z };

        if (tool === ToolType.DRAW_LINE) {
            setDrawPoints(prev => {
                if (prev.length > 2) {
                    const start = prev[0];
                    const dist = new THREE.Vector3(start.x, start.y, start.z).distanceTo(pt);
                    if (dist < 0.3) {
                        createShape(prev, tool);
                        return [];
                    }
                }
                return [...prev, newPoint];
            });
        } else if (tool === ToolType.DRAW_RECT) {
             setDrawPoints(prev => {
                 if (prev.length === 0) return [newPoint];
                 const start = prev[0];
                 const minX = Math.min(start.x, newPoint.x);
                 const maxX = Math.max(start.x, newPoint.x);
                 const minZ = Math.min(start.z, newPoint.z);
                 const maxZ = Math.max(start.z, newPoint.z);
                 const y = start.y;

                 const points: IPoint[] = [
                     { x: minX, y, z: minZ },
                     { x: maxX, y, z: minZ },
                     { x: maxX, y, z: maxZ },
                     { x: minX, y, z: maxZ },
                     { x: minX, y, z: minZ }
                 ];

                 createShape(points, tool);
                 return [];
             });
        } else if (tool === ToolType.DRAW_CIRCLE) {
             setDrawPoints(prev => {
                 if (prev.length === 0) return [newPoint];
                 const center = prev[0];
                 const radius = new THREE.Vector3(center.x, 0, center.z).distanceTo(new THREE.Vector3(newPoint.x, 0, newPoint.z));
                 const points = createCirclePoints(radius);
                 const finalPoints = points.map(p => ({ x: p.x + center.x, y: center.y, z: p.z + center.z }));
                 createShape(finalPoints, tool);
                 return [];
             });
        } else if (tool === ToolType.DRAW_ARC) {
             setDrawPoints(prev => {
                 if (prev.length === 0) return [newPoint];
                 const center = prev[0];
                 const radius = new THREE.Vector3(center.x, 0, center.z).distanceTo(new THREE.Vector3(newPoint.x, 0, newPoint.z));
                 const points = createArcPoints(radius);
                 const finalPoints = points.map(p => ({ x: p.x + center.x, y: center.y, z: p.z + center.z }));
                 createShape(finalPoints, tool);
                 return [];
             });
        }

    }, [tool, snapInfo, createShape]);

    const handlePointerDown = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) return;
        setIsDragging(true);
    }, [tool]);

    const handlePointerUp = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) return;
        setIsDragging(false);
        handleClick(e as unknown as ThreeEvent<MouseEvent>);
    }, [tool, handleClick]);

    return {
        drawPoints,
        cursorPos,
        setCursorPos,
        snapInfo,
        setSnapInfo,
        isDragging,
        drawingHeight: 0,
        handlePointerDown,
        handlePointerUp,
        handleClick,
        typedInput
    };
};

const EditorScene: React.FC<{ view: string | null; onViewFinished: () => void }> = ({ view, onViewFinished }) => {
    const { shapes, selectedIds, selectShape, tool } = useApp();
    const { ppState, handlePointerMove, handlePointerDown: ppDown, handlePointerUp: ppUp, tempShape, isDragging: isPPDragging } = usePushPullManager();
    const { drawPoints, cursorPos, setCursorPos, snapInfo, setSnapInfo, isDragging: isDrawing, drawingHeight, handlePointerDown: drawDown, handlePointerUp: drawUp, handleClick, typedInput } = useDrawingManager();
    const [isObjectDragging, setIsObjectDragging] = useState(false);

    const renderShapes = useMemo(() => {
        if (tempShape && ppState.hoveredShapeId) {
            return shapes.map(s => s.id === ppState.hoveredShapeId ? tempShape : s);
        }
        return shapes;
    }, [shapes, tempShape, ppState.hoveredShapeId]);

    const raycaster = useThree((state) => state.raycaster);
    useEffect(() => {
        raycaster.params.Line.threshold = 0.2;
    }, [raycaster]);

    const pushPullHandlers = useMemo(() => ({ handlePointerDown: ppDown, handlePointerUp: ppUp, handlePointerMove: handlePointerMove }), [ppDown, ppUp, handlePointerMove]);
    const drawingHandlers = useMemo(() => ({ handlePointerDown: drawDown, handlePointerUp: drawUp, handleClick: handleClick }), [drawDown, drawUp, handleClick]);

    // Handle global pointer move for snapping logic
    const handleGlobalMove = (e: ThreeEvent<PointerEvent>) => {
         if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) return;

         // 1. Raycast against scene objects to find surface
         const shapeIntersections = e.intersections.filter(i => (i.object.userData?.isShape || i.object.parent?.userData?.isShape) && i.object !== e.object);

         const topIntersect = shapeIntersections.length > 0 ? shapeIntersections[0] : undefined;

         let rawPos: THREE.Vector3;
         let intersectedObj = topIntersect;

         if (topIntersect) {
             rawPos = topIntersect.point;
         } else {
             // Fallback to ground plane
             const plane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0);
             const target = new THREE.Vector3();
             e.ray.intersectPlane(plane, target);
             rawPos = target || new THREE.Vector3(0, 0, 0);
         }

         // 2. Adjust for active drawing height if we are in 2D mode (Rect/Circle) and have a start point
         if (drawPoints.length > 0 && (tool === ToolType.DRAW_RECT || tool === ToolType.DRAW_CIRCLE || tool === ToolType.DRAW_ARC)) {
             // Lock Y to the start point Y (draw on the same platform)
             const fixedY = drawPoints[0].y;

             // If we are looking at a surface at a different height, projected point logic might be needed
             // But for simplicity, we project the cursor ray to the fixed Y plane
             const plane = new THREE.Plane(new THREE.Vector3(0, 1, 0), -fixedY);
             const target = new THREE.Vector3();
             e.ray.intersectPlane(plane, target);
             if (target) rawPos = target;

             intersectedObj = undefined; // Disable face snapping during 2nd phase of 2D draw to avoid jumping
         }

         // 3. Calculate Snap
         const snap = getGeometrySnap(rawPos, shapes, drawPoints, SNAP_THRESHOLD, intersectedObj);

         setCursorPos(snap.position);
         setSnapInfo(snap);
    };

    return (
        <>
            <ambientLight intensity={0.7} />
            <directionalLight position={[10, 20, 5]} intensity={1} castShadow shadow-mapSize={[2048, 2048]}>
                <orthographicCamera attach="shadow-camera" left={-20} right={20} top={20} bottom={-20} />
            </directionalLight>

            <Grid position={[0, -0.01, 0]} args={[40, 40]} cellSize={1} cellThickness={1} cellColor="#e2e8f0" sectionSize={5} sectionThickness={1.5} sectionColor="#cbd5e1" fadeDistance={50} infiniteGrid />

            {/* Global Interaction Handler */}
            <group 
                onPointerDown={(e) => {
                    if (tool !== ToolType.SELECT && tool !== ToolType.PUSH_PULL) drawDown(e);
                    else selectShape('', false); 
                }} 
                onPointerUp={(e) => {
                         if (tool !== ToolType.SELECT && tool !== ToolType.PUSH_PULL) drawUp(e);
                }}
                onPointerMove={(e) => {
                         if (tool === ToolType.PUSH_PULL) handlePointerMove(e);
                         else handleGlobalMove(e);
                }}
            >
                {/* Transparent plane for catching events in empty space */}
                <mesh rotation={[-Math.PI/2, 0, 0]} position={[0, -0.02, 0]} receiveShadow visible={false}>
                    <planeGeometry args={[1000, 1000]} />
                    <meshBasicMaterial /> 
                </mesh>
            </group>

            {renderShapes.map(shape => (
                <ShapeRenderer 
                    key={shape.id} 
                    shape={shape} 
                    isSelected={selectedIds.includes(shape.id)} 
                    onSelect={(e) => {
                        selectShape(shape.id, e.shiftKey || (tool === ToolType.SELECT && selectedIds.length > 0 && e.metaKey)); 
                    }}
                    pushPullState={ppState}
                    pushPullHandlers={pushPullHandlers}
                    drawingHandlers={drawingHandlers}
                    setDraggingState={setIsObjectDragging}
                />
            ))}

            <InteractionLayer shapes={shapes} tool={tool} setCursorPos={setCursorPos} setSnapInfo={setSnapInfo} cursorPos={cursorPos} snapInfo={snapInfo} drawPoints={drawPoints} isDragging={isDrawing} drawingHeight={drawingHeight} typedInput={typedInput} />

            <SelectionGizmo />

            <OrbitControls makeDefault minDistance={2} maxDistance={50} dampingFactor={0.1} enabled={!isDrawing && !isPPDragging && !isObjectDragging} />
            <GizmoHelper alignment="bottom-right" margin={[80, 80]}>
                <GizmoViewport axisColors={['#ef4444', '#22c55e', '#3b82f6']} labelColor="black" />
            </GizmoHelper>
            <CameraHandler view={view} onFinished={onViewFinished} />
        </>
    );
};

