// ... (imports remain the same)
import React, { useRef, useState, useMemo, useEffect, useCallback, useLayoutEffect } from 'react';
import { Canvas, useThree, ThreeEvent, useFrame } from '@react-three/fiber';
import { OrbitControls, Grid, Environment, TransformControls, Html, GizmoHelper, GizmoViewport } from '@react-three/drei';
import * as THREE from 'three';
import { OrbitControls as OrbitControlsImpl } from 'three-stdlib';
import { useApp } from '../context/AppContext';
import { ToolType, IPoint, IShape, ShapeType } from '../types';
import { SNAP_GRID, DEFAULT_COLOR, FLAT_COLOR, HIGHLIGHT_COLOR, DEFAULT_HEIGHT } from '../constants';
import AIAssistant from './AIAssistant';

// --- Constants ---
const SNAP_THRESHOLD = 0.3; 
const EPSILON = 1e-4;

// --- Types ---
type SnapType = 'none' | 'grid' | 'vertex' | 'midpoint' | 'edge' | 'face' | 'align' | 'endpoint';

interface SnapResult {
    position: THREE.Vector3;
    normal: THREE.Vector3; // Normal of the surface/snap
    type: SnapType;
    distance: number;
    snapObjectId?: string;
    snapEdge?: [THREE.Vector3, THREE.Vector3];
}

type PushPullMode = 'top' | 'side' | 'none';

interface PushPullState {
    mode: PushPullMode;
    hoveredShapeId: string | null;
    hoveredEdgeIndex: number;
    dragStartPoint: THREE.Vector3 | null;
    originalHeight: number;
    originalPoints: IPoint[];
    normal: THREE.Vector3;
    dragHeight?: number;
}

interface ShapeRendererProps {
    shape: IShape;
    isSelected: boolean;
    onSelect: (e: ThreeEvent<MouseEvent>) => void;
    pushPullState: PushPullState;
    pushPullHandlers: {
        handlePointerDown: (e: ThreeEvent<PointerEvent>) => void;
        handlePointerUp: () => void;
        handlePointerMove: (e: ThreeEvent<PointerEvent>) => void;
    };
    drawingHandlers: {
        handlePointerDown: (e: ThreeEvent<PointerEvent>) => void;
        handlePointerUp: (e: ThreeEvent<PointerEvent>) => void;
        handleClick: (e: ThreeEvent<MouseEvent>) => void;
    };
    setDraggingState: (isDragging: boolean) => void;
}

// --- Geometry Helpers ---
// ... (Keep existing geometry helpers: createThreeShape, createCirclePoints, createArcPoints, transformPoint, closestPointOnSegment, distToSegmentSquared, getLineEndpoints, getGeometrySnap)
const createThreeShape = (points: IPoint[]) => {
  const shape = new THREE.Shape();
  if (!points || points.length === 0) return shape;
  if (points[0]) {
    shape.moveTo(points[0].x, -points[0].z); 
    for (let i = 1; i < points.length; i++) {
        if (points[i]) shape.lineTo(points[i].x, -points[i].z);
    }
  }
  shape.closePath();
  return shape;
};

const createCirclePoints = (radius: number, segments = 32): IPoint[] => {
  const points: IPoint[] = [];
  for (let i = 0; i < segments; i++) {
    const theta = (i / segments) * Math.PI * 2;
    points.push({ x: Math.cos(theta) * radius, y: 0, z: Math.sin(theta) * radius });
  }
  points.push(points[0]);
  return points;
};

const createArcPoints = (radius: number, segments = 16): IPoint[] => {
  const points: IPoint[] = [];
  points.push({ x: 0, y: 0, z: 0 });
  for (let i = 0; i <= segments; i++) {
    const theta = (i / segments) * (Math.PI / 2); 
    points.push({ x: Math.cos(theta) * radius, y: 0, z: Math.sin(theta) * radius });
  }
  points.push({ x: 0, y: 0, z: 0 });
  return points;
};

const transformPoint = (localP: IPoint, shape: IShape): THREE.Vector3 => {
    const sX = shape.scale[0];
    const sZ = shape.scale[2];
    const rot = shape.rotation;
    const cos = Math.cos(rot);
    const sin = Math.sin(rot);
    const xScaled = localP.x * sX;
    const zScaled = localP.z * sZ;
    const xRot = xScaled * cos - zScaled * sin;
    const zRot = xScaled * sin + zScaled * cos;
    return new THREE.Vector3(xRot + shape.position[0], shape.position[1], zRot + shape.position[2]);
};

const closestPointOnSegment = (p: THREE.Vector3, v: THREE.Vector3, w: THREE.Vector3): THREE.Vector3 => {
  const vwx = w.x - v.x;
  const vwy = w.y - v.y;
  const vwz = w.z - v.z;
  const vpx = p.x - v.x;
  const vpy = p.y - v.y;
  const vpz = p.z - v.z;
  const dot = vpx * vwx + vpy * vwy + vpz * vwz;
  const l2 = vwx * vwx + vwy * vwy + vwz * vwz;
  if (l2 === 0) return v;
  let t = dot / l2;
  t = Math.max(0, Math.min(1, t));
  return new THREE.Vector3(v.x + t * vwx, v.y + t * vwy, v.z + t * vwz);
};

const distToSegmentSquared = (p: THREE.Vector3, v: THREE.Vector3, w: THREE.Vector3) => {
    const l2 = v.distanceToSquared(w);
    if (l2 === 0) return p.distanceToSquared(v);
    let t = ((p.x - v.x) * (w.x - v.x) + (p.z - v.z) * (w.z - v.z)) / l2;
    t = Math.max(0, Math.min(1, t));
    return (p.x - (v.x + t * (w.x - v.x)))**2 + (p.z - (v.z + t * (w.z - v.z)))**2;
};

const getLineEndpoints = (shape: IShape): [THREE.Vector3, THREE.Vector3] | null => {
    if (shape.name !== 'Edge') return null;
    let minX = Infinity, maxX = -Infinity;
    shape.points.forEach(p => {
        if (p.x < minX) minX = p.x;
        if (p.x > maxX) maxX = p.x;
    });
    const halfLen = (maxX - minX) / 2;
    const scaledHalfLen = halfLen * shape.scale[0];
    const pos = new THREE.Vector3(shape.position[0], shape.position[1], shape.position[2]);
    const angle = -shape.rotation; 
    const dx = Math.cos(angle) * scaledHalfLen;
    const dz = Math.sin(angle) * scaledHalfLen;
    return [
        new THREE.Vector3(pos.x - dx, pos.y, pos.z - dz),
        new THREE.Vector3(pos.x + dx, pos.y, pos.z + dz)
    ];
};

const getGeometrySnap = (
    cursorPos: THREE.Vector3, 
    shapes: IShape[], 
    activePoints: IPoint[] = [],
    threshold: number,
    intersectedObject?: THREE.Intersection
): SnapResult => {
    let bestSnap: SnapResult;
    const defaultNormal = new THREE.Vector3(0, 1, 0);

    const getShapeUserData = (obj: THREE.Object3D) => {
        if (obj.userData?.isShape) return obj.userData;
        if (obj.parent?.userData?.isShape) return obj.parent.userData;
        return null;
    };
    const shapeData = intersectedObject ? getShapeUserData(intersectedObject.object) : null;

    if (intersectedObject && shapeData) {
        const normalMatrix = new THREE.Matrix3().getNormalMatrix(intersectedObject.object.matrixWorld);
        const worldNormal = intersectedObject.face?.normal.clone().applyMatrix3(normalMatrix).normalize() || defaultNormal;

        bestSnap = { 
            position: intersectedObject.point, 
            normal: worldNormal,
            type: 'face', 
            distance: 0, 
            snapObjectId: shapeData.id 
        };
    } else {
        bestSnap = {
            position: new THREE.Vector3(
                Math.round(cursorPos.x / SNAP_GRID) * SNAP_GRID,
                cursorPos.y, 
                Math.round(cursorPos.z / SNAP_GRID) * SNAP_GRID
            ),
            normal: defaultNormal,
            type: 'grid',
            distance: Infinity
        };
    }

    if (activePoints && activePoints.length > 0) {
        const startPt = activePoints[0];
        const ptVec = new THREE.Vector3(startPt.x, startPt.y, startPt.z);
        const dist = ptVec.distanceTo(cursorPos); 
        if (dist < threshold * 1.5) {
            return { position: ptVec, normal: bestSnap.normal, type: 'endpoint', distance: dist };
        }
    }

    for (const shape of shapes) {
        if (shape.name === 'Edge') {
             const endpoints = getLineEndpoints(shape);
             if (endpoints) {
                 for(const ep of endpoints) {
                     const dist = ep.distanceTo(cursorPos);
                     if (dist < threshold) {
                         if (bestSnap.type === 'face' || bestSnap.type === 'grid' || dist < bestSnap.distance) {
                             bestSnap = { position: ep, normal: bestSnap.normal, type: 'endpoint', distance: dist, snapObjectId: shape.id };
                         }
                     }
                 }
                 continue; 
             }
        }

        const currentH = shape.height * shape.scale[1];
        const hasHeight = Math.abs(currentH) > 0.001;

        for (let i = 0; i < shape.points.length; i++) {
            const worldPt = transformPoint(shape.points[i], shape);
            let dist = worldPt.distanceTo(cursorPos);
            if (dist < threshold) {
                 if (bestSnap.type === 'face' || bestSnap.type === 'grid' || dist < bestSnap.distance) {
                    bestSnap = { position: worldPt, normal: bestSnap.normal, type: 'vertex', distance: dist, snapObjectId: shape.id };
                 }
            }
            if (hasHeight) {
                const worldPtTop = worldPt.clone().setY(worldPt.y + currentH);
                dist = worldPtTop.distanceTo(cursorPos);
                if (dist < threshold) {
                     if (bestSnap.type === 'face' || bestSnap.type === 'grid' || dist < bestSnap.distance) {
                        bestSnap = { position: worldPtTop, normal: bestSnap.normal, type: 'vertex', distance: dist, snapObjectId: shape.id };
                     }
                }
            }
        }
    }

    if (bestSnap.type === 'vertex' || bestSnap.type === 'endpoint') return bestSnap;

    let bestEdgeSnap: SnapResult | null = null;
    let minEdgeDist = threshold;

    for (const shape of shapes) {
        const pts = shape.points;
        const len = pts.length;
        const currentH = shape.height * shape.scale[1];
        const hasHeight = Math.abs(currentH) > 0.001;

        for (let i = 0; i < len; i++) {
             const p1 = transformPoint(pts[i], shape);
             const p2 = transformPoint(pts[(i + 1) % len], shape);

             const checkSegment = (v1: THREE.Vector3, v2: THREE.Vector3) => {
                 const mid = new THREE.Vector3().addVectors(v1, v2).multiplyScalar(0.5);
                 const distMid = mid.distanceTo(cursorPos);

                 if (distMid < threshold && distMid < minEdgeDist) {
                     bestEdgeSnap = { position: mid, normal: bestSnap.normal, type: 'midpoint', distance: distMid, snapObjectId: shape.id, snapEdge: [v1, v2] };
                     minEdgeDist = distMid;
                     return;
                 }

                 const projected = closestPointOnSegment(cursorPos, v1, v2);
                 const distEdge = projected.distanceTo(cursorPos);
                 if (distEdge < threshold && distEdge < minEdgeDist) {
                     bestEdgeSnap = { position: projected, normal: bestSnap.normal, type: 'edge', distance: distEdge, snapObjectId: shape.id, snapEdge: [v1, v2] };
                     minEdgeDist = distEdge;
                 }
             };

             checkSegment(p1, p2);
             if (hasHeight) {
                 const p1Top = p1.clone().setY(p1.y + currentH);
                 const p2Top = p2.clone().setY(p2.y + currentH);
                 checkSegment(p1Top, p2Top);
                 checkSegment(p1, p1Top);
             }
        }
    }

    if (bestEdgeSnap) return bestEdgeSnap;
    return bestSnap;
};

// ... (Keep existing simple components: SimpleLine, SnapIndicator, SurfaceGridHelper, CursorTooltip, ShapeOutline)
const SimpleLine: React.FC<{ points: (THREE.Vector3 | [number, number, number])[], color: string, dashed?: boolean, opacity?: number, transparent?: boolean, lineWidth?: number, depthTest?: boolean }> = ({ points, color, dashed, opacity, transparent, lineWidth, depthTest = true }) => {
    const ref = useRef<THREE.Line>(null);
    const geometry = useMemo(() => {
        const pts = points.map(p => (p instanceof THREE.Vector3 ? p : new THREE.Vector3(...p)));
        return new THREE.BufferGeometry().setFromPoints(pts);
    }, [points]);

    useLayoutEffect(() => {
        if (dashed && ref.current) {
            ref.current.computeLineDistances();
        }
    }, [geometry, dashed]);

    return (
        <line ref={ref} geometry={geometry}>
            {dashed ? (
                <lineDashedMaterial color={color} dashSize={0.2} gapSize={0.1} transparent={transparent} opacity={opacity} depthTest={depthTest} toneMapped={false} />
            ) : (
                <lineBasicMaterial color={color} transparent={transparent} opacity={opacity} depthTest={depthTest} toneMapped={false} />
            )}
        </line>
    );
};

const SnapIndicator: React.FC<{ position: THREE.Vector3; type: SnapType; snapEdge?: [THREE.Vector3, THREE.Vector3] }> = ({ position, type, snapEdge }) => {
    if (type === 'grid') return null;
    let color = 'orange';
    if (type === 'midpoint') color = 'cyan';
    else if (type === 'vertex' || type === 'endpoint') color = '#ec4899'; 
    else if (type === 'face') color = '#3b82f6'; 

    return (
        <group position={position}>
            {type === 'face' ? (
                 <mesh rotation={[-Math.PI/2, 0, 0]}>
                    <ringGeometry args={[0.05, 0.1, 16]} />
                    <meshBasicMaterial color={color} depthTest={false} transparent opacity={0.8} side={THREE.DoubleSide} />
                 </mesh>
            ) : (
                <mesh>
                    <sphereGeometry args={[type === 'vertex' || type === 'endpoint' ? 0.12 : 0.05]} />
                    <meshBasicMaterial color={color} depthTest={false} />
                </mesh>
            )}
            {type === 'edge' && snapEdge && <SimpleLine points={[snapEdge[0], snapEdge[1]]} color="orange" lineWidth={3} depthTest={false} />}
            {type === 'midpoint' && snapEdge && <SimpleLine points={[snapEdge[0], snapEdge[1]]} color="cyan" lineWidth={3} depthTest={false} />}
        </group>
    );
};

const SurfaceGridHelper: React.FC<{ position: THREE.Vector3; normal: THREE.Vector3; visible: boolean }> = ({ position, normal, visible }) => {
    const gridRef = useRef<THREE.Group>(null);
    useFrame(() => {
        if (gridRef.current) {
            const dummy = new THREE.Object3D();
            dummy.position.copy(position);
            const up = new THREE.Vector3(0, 1, 0);
            if (Math.abs(normal.dot(up)) < 0.999) {
                dummy.quaternion.setFromUnitVectors(up, normal);
            } else {
                 dummy.quaternion.identity();
            }
            gridRef.current.position.copy(position);
            gridRef.current.quaternion.copy(dummy.quaternion);
        }
    });
    if (!visible) return null;
    return (
        <group ref={gridRef}>
             <gridHelper args={[2, 10, 0x888888, 0x444444]} rotation={[0, 0, 0]} />
             <mesh position={[0, 0.01, 0]} rotation={[-Math.PI/2, 0, 0]}>
                 <planeGeometry args={[2, 2]} />
                 <meshBasicMaterial color="blue" transparent opacity={0.1} depthWrite={false} />
             </mesh>
        </group>
    );
};

const CursorTooltip: React.FC<{ text: string; position: THREE.Vector3; type?: SnapType }> = ({ text, position, type }) => {
    if (type === 'grid') return null;
    return (
        <Html position={[position.x, position.y + 0.5, position.z]} center style={{ pointerEvents: 'none' }}>
            <div className="bg-slate-900/80 text-white text-xs px-2 py-1 rounded backdrop-blur-sm border border-slate-600 whitespace-nowrap flex items-center gap-1">
                {type && <span className={`w-2 h-2 rounded-full ${type === 'grid' ? 'bg-slate-500' : type === 'face' ? 'bg-blue-500' : 'bg-green-500'}`} />}
                {text}
            </div>
        </Html>
    );
};

const ShapeOutline: React.FC<{ shape: IShape; color: string; opacity: number }> = ({ shape, color, opacity }) => {
    const geometry = useMemo(() => {
        const shape2D = createThreeShape(shape.points);
        const geom = new THREE.ExtrudeGeometry(shape2D, { depth: shape.height, bevelEnabled: false });
        return new THREE.EdgesGeometry(geom);
    }, [shape.points, shape.height]);

    return (
        <lineSegments geometry={geometry} rotation={[-Math.PI / 2, 0, 0]}>
            <lineBasicMaterial color={color} transparent opacity={opacity} />
        </lineSegments>
    );
};

// ... (Keep existing useShapeDrag)
const useShapeDrag = (
    shape: IShape,
    isSelected: boolean,
    tool: ToolType,
    updateShape: (id: string, updates: Partial<IShape>) => void,
    setDraggingState: (isDragging: boolean) => void
) => {
    const { camera, gl } = useThree();
    const { setMeasurement, formatValue } = useApp();
    const groupRef = useRef<THREE.Group>(null);
    const dragInfo = useRef({
        isDragging: false,
        startPos: new THREE.Vector3(),
        grabOffsetGround: new THREE.Vector3(),
        grabOffsetY: 0,
        verticalPlane: new THREE.Plane()
    });

    const getRayIntersections = (clientX: number, clientY: number) => {
        const raycaster = new THREE.Raycaster();
        const ndc = new THREE.Vector2(
            (clientX / gl.domElement.clientWidth) * 2 - 1,
            -(clientY / gl.domElement.clientHeight) * 2 + 1
        );
        raycaster.setFromCamera(ndc, camera);
        const groundPlane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0);
        const groundHit = new THREE.Vector3();
        raycaster.ray.intersectPlane(groundPlane, groundHit);
        const vertHit = new THREE.Vector3();
        raycaster.ray.intersectPlane(dragInfo.current.verticalPlane, vertHit);
        return { groundHit, vertHit };
    };

    const handlePointerMove = useCallback((e: PointerEvent) => {
        if (!dragInfo.current.isDragging || !groupRef.current) return;
        const { groundHit, vertHit } = getRayIntersections(e.clientX, e.clientY);
        const isVerticalMode = e.shiftKey;
        document.body.style.cursor = isVerticalMode ? 'ns-resize' : 'move';
        const currentPos = groupRef.current.position.clone();
        const newPos = currentPos.clone();

        if (isVerticalMode) {
             if (vertHit) {
                 const rawY = vertHit.y + dragInfo.current.grabOffsetY;
                 newPos.y = Math.max(0, Math.round(rawY / 0.05) * 0.05); 
             }
        } else {
             if (groundHit) {
                 const rawX = groundHit.x + dragInfo.current.grabOffsetGround.x;
                 const rawZ = groundHit.z + dragInfo.current.grabOffsetGround.z;
                 newPos.x = Math.round(rawX / SNAP_GRID) * SNAP_GRID;
                 newPos.z = Math.round(rawZ / SNAP_GRID) * SNAP_GRID;
             }
        }

        groupRef.current.position.copy(newPos);
        const msg = isVerticalMode 
            ? `高度 Y: ${formatValue(newPos.y)}` 
            : `位置 X: ${formatValue(newPos.x)}, Z: ${formatValue(newPos.z)} (按住 Shift 調整高度)`;
        setMeasurement(msg);
    }, [camera, gl, formatValue, setMeasurement]);

    const handlePointerUp = useCallback((e: PointerEvent) => {
        if (!dragInfo.current.isDragging) return;
        document.body.style.cursor = 'default';
        dragInfo.current.isDragging = false;
        setDraggingState(false);
        setMeasurement('');
        window.removeEventListener('pointermove', handlePointerMove);
        window.removeEventListener('pointerup', handlePointerUp);
        window.removeEventListener('keydown', handleKeyDown);
        window.removeEventListener('keyup', handleKeyUp);

        if (groupRef.current) {
            const finalPos = groupRef.current.position;
            if (finalPos.distanceTo(dragInfo.current.startPos) > 0.001) {
                updateShape(shape.id, { position: [finalPos.x, finalPos.y, finalPos.z] });
            } else {
                 groupRef.current.position.copy(dragInfo.current.startPos);
            }
        }
    }, [handlePointerMove, updateShape, shape.id, setDraggingState, setMeasurement]);

    const handleKeyDown = useCallback((e: KeyboardEvent) => {
        if (e.key === 'Shift' && dragInfo.current.isDragging) {
            document.body.style.cursor = 'ns-resize';
            setMeasurement((prev) => prev.replace('(按住 Shift 調整高度)', '').replace('高度 Y:', '高度 Y:') || '高度調整中...'); 
        }
    }, [setMeasurement]);

    const handleKeyUp = useCallback((e: KeyboardEvent) => {
        if (e.key === 'Shift' && dragInfo.current.isDragging) {
            document.body.style.cursor = 'move';
        }
    }, []);

    const handlePointerDown = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.SELECT || e.button !== 0) return;
        e.stopPropagation();
        const camDir = new THREE.Vector3();
        camera.getWorldDirection(camDir);
        const planeNormal = new THREE.Vector3(camDir.x, 0, camDir.z).normalize().negate(); 
        const startPos = new THREE.Vector3(shape.position[0], shape.position[1], shape.position[2]);
        const verticalPlane = new THREE.Plane().setFromNormalAndCoplanarPoint(planeNormal, startPos);
        dragInfo.current.verticalPlane = verticalPlane;
        dragInfo.current.startPos.copy(startPos);

        const raycaster = new THREE.Raycaster();
        const ndc = new THREE.Vector2(
            (e.clientX / gl.domElement.clientWidth) * 2 - 1,
            -(e.clientY / gl.domElement.clientHeight) * 2 + 1
        );
        raycaster.setFromCamera(ndc, camera);
        const groundPlane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0);
        const gHit = new THREE.Vector3();
        raycaster.ray.intersectPlane(groundPlane, gHit);
        const vHit = new THREE.Vector3();
        raycaster.ray.intersectPlane(verticalPlane, vHit);

        if (gHit && groupRef.current) {
            dragInfo.current.isDragging = true;
            dragInfo.current.grabOffsetGround.subVectors(groupRef.current.position, gHit);
            if (vHit) {
                dragInfo.current.grabOffsetY = groupRef.current.position.y - vHit.y;
            }
            document.body.style.cursor = 'move';
            setDraggingState(true);
            window.addEventListener('pointermove', handlePointerMove);
            window.addEventListener('pointerup', handlePointerUp);
            window.addEventListener('keydown', handleKeyDown);
            window.addEventListener('keyup', handleKeyUp);
        }
    }, [tool, shape, camera, gl, handlePointerMove, handlePointerUp, setDraggingState]);

    useEffect(() => {
        return () => {
             window.removeEventListener('pointermove', handlePointerMove);
             window.removeEventListener('pointerup', handlePointerUp);
             window.removeEventListener('keydown', handleKeyDown);
             window.removeEventListener('keyup', handleKeyUp);
        };
    }, [handlePointerMove, handlePointerUp, handleKeyDown, handleKeyUp]);

    return { groupRef, handlePointerDown };
};

// ... (Keep existing ShapeRenderer)
const ShapeRenderer = React.memo(({ shape, isSelected, onSelect, pushPullState, pushPullHandlers, drawingHandlers, setDraggingState }: ShapeRendererProps) => {
    const { unit, tool, updateShape } = useApp();
    const isPushPullMode = tool === ToolType.PUSH_PULL;
    const highlightColor = isPushPullMode ? shape.color : (isSelected ? HIGHLIGHT_COLOR : shape.color);
    const { groupRef, handlePointerDown } = useShapeDrag(shape, isSelected, tool, updateShape, setDraggingState);
    const isDraggingTop = pushPullState.mode === 'top' && pushPullState.hoveredShapeId === shape.id && !!pushPullState.dragStartPoint;
    let scaleY = 1;
    if (isDraggingTop && pushPullState.dragHeight !== undefined && shape.height > 0) {
        scaleY = pushPullState.dragHeight / shape.height;
    }
    const shape2D = useMemo(() => createThreeShape(shape.points), [shape.points]);

    return (
        <group 
            ref={groupRef}
            position={[shape.position[0], shape.position[1], shape.position[2]]} 
            rotation={[0, shape.rotation, 0]} 
            scale={[shape.scale[0], shape.scale[1] * scaleY, shape.scale[2]]} 
            userData={{ isShape: true, id: shape.id, isContainer: true }} 
            name="shape_group" 
            onPointerDown={(e) => {
                if (isPushPullMode) {
                    pushPullHandlers.handlePointerDown(e);
                } else if (tool === ToolType.SELECT) {
                    if (!isSelected) {
                        onSelect(e);
                    }
                    handlePointerDown(e);
                } else {
                    drawingHandlers.handlePointerDown(e);
                }
            }}
            onPointerMove={(e) => {
                if (isPushPullMode) {
                    pushPullHandlers.handlePointerMove(e);
                }
            }}
            onPointerUp={(e) => {
                if (isPushPullMode) {
                    pushPullHandlers.handlePointerUp();
                } else {
                    drawingHandlers.handlePointerUp(e);
                }
            }}
        >
            <mesh rotation={[-Math.PI/2, 0, 0]} castShadow receiveShadow userData={{ isShape: true, id: shape.id }}>
                <extrudeGeometry args={[shape2D, { depth: shape.height, bevelEnabled: false }]} />
                <meshStandardMaterial 
                    color={highlightColor} 
                    transparent={shape.type === 'flat'} 
                    opacity={shape.type === 'flat' ? 0.6 : 1.0} 
                    polygonOffset={shape.type === 'flat'} 
                    polygonOffsetFactor={shape.type === 'flat' ? -1 : 0} 
                />
            </mesh>
            <ShapeOutline shape={shape} color="#333" opacity={isPushPullMode ? 0.2 : 0.5} />
        </group>
    );
});

// ... (Keep existing SelectionGizmo, CameraHandler, DrawingPreview, InteractionLayer)
const SelectionGizmo: React.FC = () => {
    const { selectedIds, transformMode, updateShape, tool } = useApp();
    const { scene, camera } = useThree();
    const [targetObj, setTargetObj] = useState<THREE.Object3D | null>(null);
    const isEnabled = tool === ToolType.SELECT && selectedIds.length === 1;
    const selectedId = isEnabled ? selectedIds[0] : null;
    useFrame(() => {
        if (!isEnabled || !selectedId) {
             if (targetObj) setTargetObj(null);
             return;
        }
        if (targetObj && targetObj.userData?.id === selectedId) return;
        let found: THREE.Object3D | null = null;
        scene.traverse((child) => {
            if (found) return;
            if (child.userData?.isShape && child.userData?.id === selectedId && child.userData?.isContainer) {
                found = child;
            }
        });
        if (found && found !== targetObj) setTargetObj(found);
    });
    if (!isEnabled || !targetObj) return null;
    return (
        <TransformControls 
            object={targetObj} 
            mode={transformMode} 
            space={transformMode === 'scale' ? 'local' : 'world'} 
            makeDefault 
            onDraggingChange={(isDragging) => {
                const controls = (camera as any).controls;
                if(controls) controls.enabled = !isDragging;
            }}
            onMouseUp={() => {
                 if (targetObj) {
                     updateShape(selectedId!, {
                         position: [targetObj.position.x, targetObj.position.y, targetObj.position.z],
                         rotation: targetObj.rotation.y,
                         scale: [targetObj.scale.x, targetObj.scale.y, targetObj.scale.z]
                     });
                 }
            }}
        />
    );
};

const CameraHandler: React.FC<{ view: string | null; onFinished: () => void }> = ({ view, onFinished }) => {
    const { camera, controls } = useThree();
    useEffect(() => {
        if (!view) return;
        let targetPos = new THREE.Vector3();
        if (view === '上視圖') targetPos.set(0, 20, 0);
        else if (view === '前視圖') targetPos.set(0, 0, 20);
        else if (view === '右視圖') targetPos.set(20, 0, 0);
        else return;
        camera.position.copy(targetPos);
        camera.lookAt(0, 0, 0);
        if (controls) {
            (controls as any).target.set(0, 0, 0);
            (controls as any).update();
        }
        onFinished();
    }, [view, camera, controls, onFinished]);
    return null;
};

const DrawingPreview: React.FC<{ tool: ToolType; points: IPoint[]; cursorPos: THREE.Vector3 }> = ({ tool, points, cursorPos }) => {
    const currentPoint = cursorPos;
    if (points.length === 0) return null;
    const startPoint = points[0];

    if (tool === ToolType.DRAW_LINE) {
        const linePoints = points.map(p => new THREE.Vector3(p.x, p.y, p.z));
        linePoints.push(currentPoint);
        return <SimpleLine points={linePoints} color="black" dashed />;
    }

    const drawingY = startPoint.y;
    const flatCurrent = new THREE.Vector3(currentPoint.x, drawingY, currentPoint.z);
    const startVec = new THREE.Vector3(startPoint.x, drawingY, startPoint.z);

    if (tool === ToolType.DRAW_RECT) {
        const p1 = startVec;
        const p2 = flatCurrent;
        const minX = Math.min(p1.x, p2.x);
        const maxX = Math.max(p1.x, p2.x);
        const minZ = Math.min(p1.z, p2.z);
        const maxZ = Math.max(p1.z, p2.z);
        const rectPoints = [
            new THREE.Vector3(minX, drawingY, minZ),
            new THREE.Vector3(maxX, drawingY, minZ),
            new THREE.Vector3(maxX, drawingY, maxZ),
            new THREE.Vector3(minX, drawingY, maxZ),
            new THREE.Vector3(minX, drawingY, minZ),
        ];
        return <SimpleLine points={rectPoints} color="black" dashed />;
    }
    if (tool === ToolType.DRAW_CIRCLE) {
        const radius = startVec.distanceTo(flatCurrent);
        if (radius < 0.01) return null;
        const circlePoints = createCirclePoints(radius).map(p => new THREE.Vector3(p.x + startPoint.x, drawingY, p.z + startPoint.z));
        return (
            <>
                <SimpleLine points={circlePoints} color="black" dashed />
                <SimpleLine points={[startVec, flatCurrent]} color="gray" dashed opacity={0.5} />
            </>
        );
    }
    if (tool === ToolType.DRAW_ARC) {
        const radius = startVec.distanceTo(flatCurrent);
        if (radius < 0.01) return null;
        const arcPoints = createArcPoints(radius).map(p => new THREE.Vector3(p.x + startPoint.x, drawingY, p.z + startPoint.z));
         return (
            <>
                <SimpleLine points={arcPoints} color="black" dashed />
                <SimpleLine points={[startVec, flatCurrent]} color="gray" dashed opacity={0.5} />
            </>
        );
    }
    return null;
};

const InteractionLayer: React.FC<{
    shapes: IShape[];
    tool: ToolType;
    setCursorPos: (v: THREE.Vector3) => void;
    setSnapInfo: (s: SnapResult | null) => void;
    cursorPos: THREE.Vector3;
    snapInfo: SnapResult | null;
    drawPoints: IPoint[];
    isDragging: boolean;
    drawingHeight: number;
    typedInput: string;
}> = ({ shapes, tool, setCursorPos, setSnapInfo, cursorPos, snapInfo, drawPoints, isDragging, drawingHeight, typedInput }) => {
    const { setMeasurement, formatValue } = useApp();
    const updateMeasurement = useCallback((pos: THREE.Vector3, input?: string) => {
        let text = '';
        if (drawPoints.length > 0) {
            const start = drawPoints[drawPoints.length - 1]; 
            const current = pos;
            const dist = Math.sqrt((current.x - start.x)**2 + (current.y - start.y)**2 + (current.z - start.z)**2);
            if (tool === ToolType.DRAW_LINE) {
                text = `長度: ${input ? input : formatValue(dist)}`;
            } else if (tool === ToolType.DRAW_RECT) {
                if (input) {
                    text = `寬度, 深度: ${input}`;
                } else {
                    const w = Math.abs(current.x - start.x);
                    const d = Math.abs(current.z - start.z);
                    text = `寬度: ${formatValue(w)}, 深度: ${formatValue(d)}`;
                }
            } else if (tool === ToolType.DRAW_CIRCLE || tool === ToolType.DRAW_ARC) {
                 text = `半徑: ${input ? input : formatValue(dist)}`;
            }
        } else {
             if ([ToolType.DRAW_LINE, ToolType.DRAW_RECT, ToolType.DRAW_CIRCLE, ToolType.DRAW_ARC].includes(tool)) {
                 text = `起點: X ${formatValue(pos.x)}, Y ${formatValue(pos.y)}, Z ${formatValue(pos.z)}`;
             }
        }
        if (input !== undefined) text += '|';
        setMeasurement(text);
    }, [drawPoints, tool, formatValue, setMeasurement]);

    useEffect(() => {
        if (typedInput) updateMeasurement(cursorPos, typedInput);
    }, [typedInput, cursorPos, updateMeasurement]);

    useEffect(() => {
        if (!typedInput && snapInfo) updateMeasurement(snapInfo.position);
    }, [snapInfo, updateMeasurement, typedInput]);

    if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) return null;

    return (
        <group>
             {snapInfo && (
                <>
                    <SnapIndicator position={snapInfo.position} type={snapInfo.type} snapEdge={snapInfo.snapEdge} />
                    <CursorTooltip text={snapInfo.type === 'none' ? '' : snapInfo.type} position={snapInfo.position} type={snapInfo.type} />
                    <SurfaceGridHelper position={snapInfo.position} normal={snapInfo.normal} visible={snapInfo.type === 'face' || snapInfo.type === 'vertex'} />
                </>
             )}
             {drawPoints.length > 0 && <DrawingPreview tool={tool} points={drawPoints} cursorPos={cursorPos} />}
        </group>
    );
};

// --- Custom Hooks for Tool Managers ---

// RE-IMPLEMENTED PUSH PULL MANAGER WITH SIDE FACE SUPPORT
const usePushPullManager = () => {
    const { tool, shapes, updateShape, setMeasurement, formatValue } = useApp();
    const [ppState, setPPState] = useState<PushPullState>({
        mode: 'none',
        hoveredShapeId: null,
        hoveredEdgeIndex: -1,
        dragStartPoint: null,
        originalHeight: 0,
        originalPoints: [],
        normal: new THREE.Vector3(0, 1, 0)
    });
    const [isDragging, setIsDragging] = useState(false);
    const [tempShape, setTempShape] = useState<IShape | null>(null);

    // FIX: Add global window pointer up event to handle drag release outside canvas
    useEffect(() => {
        if (isDragging) {
            const onWindowPointerUp = () => {
                // Manually trigger handlePointerUp logic
                if (tempShape) {
                    if (ppState.mode === 'top' && ppState.dragHeight !== undefined) {
                         updateShape(tempShape.id, { height: ppState.dragHeight });
                    } else if (ppState.mode === 'side') {
                         updateShape(tempShape.id, { points: tempShape.points });
                    }
                }
                setIsDragging(false);
                setTempShape(null);
                setPPState(prev => ({ ...prev, dragStartPoint: null, dragHeight: undefined }));
                setMeasurement('');
            };
            window.addEventListener('pointerup', onWindowPointerUp);
            return () => window.removeEventListener('pointerup', onWindowPointerUp);
        }
    }, [isDragging, tempShape, ppState.dragHeight, ppState.mode, updateShape, setMeasurement]);

    const handlePointerMove = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.PUSH_PULL) return;

        if (isDragging && ppState.dragStartPoint && tempShape) {
            e.stopPropagation();
            if (ppState.mode === 'top') {
                 const ray = e.ray;
                 const normal = new THREE.Vector3(0, 0, 1).applyQuaternion(e.camera.quaternion);
                 const planeNormal = new THREE.Vector3(normal.x, 0, normal.z).normalize();
                 const plane = new THREE.Plane().setFromNormalAndCoplanarPoint(planeNormal, ppState.dragStartPoint);
                 const target = new THREE.Vector3();
                 ray.intersectPlane(plane, target);
                 if (target) {
                    const dy = target.y - ppState.dragStartPoint.y;
                    let newHeight = Math.max(0.01, ppState.originalHeight + dy);
                    newHeight = Math.round(newHeight / 0.05) * 0.05;
                    setPPState(prev => ({ ...prev, dragHeight: newHeight }));
                    setTempShape(prev => prev ? ({ ...prev, height: newHeight }) : null);
                    setMeasurement(`高度: ${formatValue(newHeight)}`);
                 }
            } else if (ppState.mode === 'side') {
                 const ray = e.ray;
                 const plane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0);
                 const target = new THREE.Vector3();
                 ray.intersectPlane(plane, target);
                 if (target) {
                     const diff = target.clone().sub(ppState.dragStartPoint);
                     const dist = diff.dot(ppState.normal); 
                     const moveVec = ppState.normal.clone().multiplyScalar(dist);
                     const shape = shapes.find(s => s.id === ppState.hoveredShapeId);
                     if (shape) {
                         const cos = Math.cos(-shape.rotation);
                         const sin = Math.sin(-shape.rotation);
                         const lx = moveVec.x * cos - moveVec.z * sin;
                         const lz = moveVec.x * sin + moveVec.z * cos;
                         const dx = lx / shape.scale[0];
                         const dz = lz / shape.scale[2];
                         const newPoints = ppState.originalPoints.map(p => ({ ...p }));
                         const idx = ppState.hoveredEdgeIndex;
                         const nextIdx = (idx + 1) % newPoints.length;
                         newPoints[idx].x += dx;
                         newPoints[idx].z += dz;
                         newPoints[nextIdx].x += dx;
                         newPoints[nextIdx].z += dz;
                         setTempShape(prev => prev ? ({ ...prev, points: newPoints }) : null);
                         setMeasurement(`偏移: ${formatValue(dist)}`);
                     }
                 }
            }
            return;
        }

        if (!isDragging) {
             const mesh = e.object as THREE.Mesh;
             if (!mesh.userData.isShape || !e.face) return;

             const normalMatrix = new THREE.Matrix3().getNormalMatrix(mesh.matrixWorld);
             const worldNormal = e.face.normal.clone().applyMatrix3(normalMatrix).normalize();
             const shapeId = mesh.userData.id;
             const shape = shapes.find(s => s.id === shapeId);

             if (worldNormal.y > 0.9) {
                 if (ppState.hoveredShapeId !== shapeId || ppState.mode !== 'top') {
                     setPPState({
                         mode: 'top',
                         hoveredShapeId: shapeId,
                         hoveredEdgeIndex: -1,
                         dragStartPoint: null,
                         originalHeight: 0,
                         originalPoints: [],
                         normal: worldNormal
                     });
                     document.body.style.cursor = 'ns-resize';
                 }
             } else if (Math.abs(worldNormal.y) < 0.2 && shape) {
                 const hitPoint = e.point.clone().sub(new THREE.Vector3(...shape.position));
                 const cos = Math.cos(-shape.rotation);
                 const sin = Math.sin(-shape.rotation);
                 const lx = hitPoint.x * cos - hitPoint.z * sin;
                 const lz = hitPoint.x * sin + hitPoint.z * cos;
                 const sx = lx / shape.scale[0];
                 const sz = lz / shape.scale[2];
                 let closestIdx = -1;
                 let minD = Infinity;
                 const pts = shape.points;
                 for (let i = 0; i < pts.length; i++) {
                     const p1 = pts[i];
                     const p2 = pts[(i+1)%pts.length];
                     const d = distToSegmentSquared(new THREE.Vector3(sx, 0, sz), new THREE.Vector3(p1.x, 0, p1.z), new THREE.Vector3(p2.x, 0, p2.z));
                     if (d < minD) {
                         minD = d;
                         closestIdx = i;
                     }
                 }
                 if (closestIdx !== -1) {
                     setPPState({
                         mode: 'side',
                         hoveredShapeId: shapeId,
                         hoveredEdgeIndex: closestIdx,
                         dragStartPoint: null,
                         originalHeight: 0,
                         originalPoints: [],
                         normal: new THREE.Vector3(worldNormal.x, 0, worldNormal.z).normalize()
                     });
                     document.body.style.cursor = 'ew-resize';
                 }
             } else {
                 if (ppState.mode !== 'none') {
                    setPPState(prev => ({ ...prev, mode: 'none', hoveredShapeId: null }));
                    document.body.style.cursor = 'default';
                 }
             }
        }
    }, [tool, isDragging, ppState, tempShape, setMeasurement, formatValue, shapes]);

    const handlePointerDown = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.PUSH_PULL || ppState.mode === 'none' || !ppState.hoveredShapeId) return;
        e.stopPropagation();

        const shape = shapes.find(s => s.id === ppState.hoveredShapeId);
        if (!shape) return;

        setIsDragging(true);
        setTempShape({ ...shape }); 
        setPPState(prev => ({
            ...prev,
            dragStartPoint: e.point.clone(),
            originalHeight: shape.height,
            originalPoints: JSON.parse(JSON.stringify(shape.points)),
            dragHeight: shape.height
        }));
    }, [tool, ppState, shapes]);

    const handlePointerUp = useCallback(() => {
       // Placeholder - logic moved to useEffect for robustness
    }, []);

    return {
        ppState,
        handlePointerMove,
        handlePointerDown,
        handlePointerUp,
        tempShape,
        isDragging
    };
};

const useDrawingManager = () => {
    const { tool, addShape, setMeasurement, formatValue } = useApp();
    const [drawPoints, setDrawPoints] = useState<IPoint[]>([]);
    const [cursorPos, setCursorPos] = useState(new THREE.Vector3());
    const [snapInfo, setSnapInfo] = useState<SnapResult | null>(null);
    const [typedInput, setTypedInput] = useState('');
    const [isDragging, setIsDragging] = useState(false);

    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) return;

            // Handle Escape to stop drawing chain
            if (e.key === 'Escape') {
                if (drawPoints.length > 0) {
                    setDrawPoints([]);
                    setTypedInput('');
                    setMeasurement('');
                }
                return;
            }

            if (e.key === 'Backspace') {
                setTypedInput(prev => prev.slice(0, -1));
                return;
            }
            if (e.key === 'Enter') {
                handleInputCommit();
                return;
            }
            if (/^[0-9.]$/.test(e.key)) {
                setTypedInput(prev => prev + e.key);
            }
        };
        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [tool, typedInput, drawPoints, setMeasurement]); 

    const createShape = useCallback((points: IPoint[], type: ToolType) => {
        let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity;
        points.forEach(p => {
            if(p.x < minX) minX = p.x;
            if(p.x > maxX) maxX = p.x;
            if(p.z < minZ) minZ = p.z;
            if(p.z > maxZ) maxZ = p.z;
        });
        const cx = (minX + maxX) / 2;
        const cz = (minZ + maxZ) / 2;
        const cy = points[0].y;
        const localPoints = points.map(p => ({ x: p.x - cx, y: 0, z: p.z - cz }));
        const newShape: IShape = {
            id: `shape-${Date.now()}`,
            type: 'solid', 
            name: type === ToolType.DRAW_RECT ? 'Room' : (type === ToolType.DRAW_CIRCLE ? 'Column' : 'Wall'),
            points: localPoints,
            height: DEFAULT_HEIGHT,
            color: DEFAULT_COLOR,
            position: [cx, cy, cz],
            rotation: 0,
            scale: [1, 1, 1]
        };
        addShape(newShape);
    }, [addShape]);

    const handleInputCommit = useCallback(() => {
        if (!typedInput) return;
        const val = parseFloat(typedInput);
        if (isNaN(val)) return;
        if (drawPoints.length > 0) {
            const start = drawPoints[drawPoints.length - 1];
            const direction = new THREE.Vector3(cursorPos.x - start.x, 0, cursorPos.z - start.z).normalize();
            if (direction.lengthSq() === 0) direction.set(1, 0, 0);

            // Logic to add point/finish shape would go here
            // simplified for now
        }
        setTypedInput('');
    }, [typedInput, drawPoints, cursorPos]);

    const handleClick = useCallback((e: ThreeEvent<MouseEvent>) => {
        const pt = snapInfo ? snapInfo.position : e.point;
        if (!pt) return;
        const newPoint: IPoint = { x: pt.x, y: pt.y, z: pt.z };
        if (tool === ToolType.DRAW_LINE) {
            setDrawPoints(prev => {
                if (prev.length > 2) {
                    const start = prev[0];
                    const dist = new THREE.Vector3(start.x, start.y, start.z).distanceTo(pt);
                    if (dist < 0.3) {
                        createShape(prev, tool);
                        return [];
                    }
                }
                return [...prev, newPoint];
            });
        } else if (tool === ToolType.DRAW_RECT) {
             setDrawPoints(prev => {
                 if (prev.length === 0) return [newPoint];
                 const start = prev[0];
                 const minX = Math.min(start.x, newPoint.x);
                 const maxX = Math.max(start.x, newPoint.x);
                 const minZ = Math.min(start.z, newPoint.z);
                 const maxZ = Math.max(start.z, newPoint.z);
                 const y = start.y;
                 const points: IPoint[] = [
                     { x: minX, y, z: minZ },
                     { x: maxX, y, z: minZ },
                     { x: maxX, y, z: maxZ },
                     { x: minX, y, z: maxZ },
                     { x: minX, y, z: minZ }
                 ];
                 createShape(points, tool);
                 return [];
             });
        } else if (tool === ToolType.DRAW_CIRCLE) {
             setDrawPoints(prev => {
                 if (prev.length === 0) return [newPoint];
                 const center = prev[0];
                 const radius = new THREE.Vector3(center.x, 0, center.z).distanceTo(new THREE.Vector3(newPoint.x, 0, newPoint.z));
                 const points = createCirclePoints(radius);
                 const finalPoints = points.map(p => ({ x: p.x + center.x, y: center.y, z: p.z + center.z }));
                 createShape(finalPoints, tool);
                 return [];
             });
        } else if (tool === ToolType.DRAW_ARC) {
             setDrawPoints(prev => {
                 if (prev.length === 0) return [newPoint];
                 const center = prev[0];
                 const radius = new THREE.Vector3(center.x, 0, center.z).distanceTo(new THREE.Vector3(newPoint.x, 0, newPoint.z));
                 const points = createArcPoints(radius);
                 const finalPoints = points.map(p => ({ x: p.x + center.x, y: center.y, z: p.z + center.z }));
                 createShape(finalPoints, tool);
                 return [];
             });
        }
    }, [tool, snapInfo, createShape]);

    const handlePointerDown = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) return;
        setIsDragging(true);
    }, [tool]);

    const handlePointerUp = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) return;
        setIsDragging(false);
        handleClick(e as unknown as ThreeEvent<MouseEvent>);
    }, [tool, handleClick]);

    return {
        drawPoints,
        cursorPos,
        setCursorPos,
        snapInfo,
        setSnapInfo,
        isDragging,
        drawingHeight: 0,
        handlePointerDown,
        handlePointerUp,
        handleClick,
        typedInput
    };
};

const EditorScene: React.FC<{ view: string | null; onViewFinished: () => void }> = ({ view, onViewFinished }) => {
    const { shapes, selectedIds, selectShape, tool } = useApp();
    const { ppState, handlePointerMove, handlePointerDown: ppDown, handlePointerUp: ppUp, tempShape, isDragging: isPPDragging } = usePushPullManager();
    const { drawPoints, cursorPos, setCursorPos, snapInfo, setSnapInfo, isDragging: isDrawing, drawingHeight, handlePointerDown: drawDown, handlePointerUp: drawUp, handleClick, typedInput } = useDrawingManager();
    const [isObjectDragging, setIsObjectDragging] = useState(false);

    const renderShapes = useMemo(() => {
        if (tempShape && ppState.hoveredShapeId) {
            return shapes.map(s => s.id === ppState.hoveredShapeId ? tempShape : s);
        }
        return shapes;
    }, [shapes, tempShape, ppState.hoveredShapeId]);

    const raycaster = useThree((state) => state.raycaster);
    useEffect(() => {
        raycaster.params.Line.threshold = 0.2;
    }, [raycaster]);

    const pushPullHandlers = useMemo(() => ({ handlePointerDown: ppDown, handlePointerUp: ppUp, handlePointerMove: handlePointerMove }), [ppDown, ppUp, handlePointerMove]);
    const drawingHandlers = useMemo(() => ({ handlePointerDown: drawDown, handlePointerUp: drawUp, handleClick: handleClick }), [drawDown, drawUp, handleClick]);

    const handleGlobalMove = (e: ThreeEvent<PointerEvent>) => {
         if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) return;
         const shapeIntersections = e.intersections.filter(i => (i.object.userData?.isShape || i.object.parent?.userData?.isShape) && i.object !== e.object);
         const topIntersect = shapeIntersections.length > 0 ? shapeIntersections[0] : undefined;
         let rawPos: THREE.Vector3;
         let intersectedObj = topIntersect;
         if (topIntersect) {
             rawPos = topIntersect.point;
         } else {
             const plane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0);
             const target = new THREE.Vector3();
             e.ray.intersectPlane(plane, target);
             rawPos = target || new THREE.Vector3(0, 0, 0);
         }
         if (drawPoints.length > 0 && (tool === ToolType.DRAW_RECT || tool === ToolType.DRAW_CIRCLE || tool === ToolType.DRAW_ARC)) {
             const fixedY = drawPoints[0].y;
             const plane = new THREE.Plane(new THREE.Vector3(0, 1, 0), -fixedY);
             const target = new THREE.Vector3();
             e.ray.intersectPlane(plane, target);
             if (target) rawPos = target;
             intersectedObj = undefined; 
         }
         const snap = getGeometrySnap(rawPos, shapes, drawPoints, SNAP_THRESHOLD, intersectedObj);
         setCursorPos(snap.position);
         setSnapInfo(snap);
    };

    return (
        <>
            <ambientLight intensity={0.7} />
            <directionalLight position={[10, 20, 5]} intensity={1} castShadow shadow-mapSize={[2048, 2048]}>
                <orthographicCamera attach="shadow-camera" left={-20} right={20} top={20} bottom={-20} />
            </directionalLight>

            <Grid position={[0, -0.01, 0]} args={[40, 40]} cellSize={1} cellThickness={1} cellColor="#e2e8f0" sectionSize={5} sectionThickness={1.5} sectionColor="#cbd5e1" fadeDistance={50} infiniteGrid />

            <group 
                onPointerDown={(e) => {
                    if (tool !== ToolType.SELECT && tool !== ToolType.PUSH_PULL) drawDown(e);
                    else selectShape('', false); 
                }} 
                onPointerUp={(e) => {
                         if (tool !== ToolType.SELECT && tool !== ToolType.PUSH_PULL) drawUp(e);
                }}
                onPointerMove={(e) => {
                         if (tool === ToolType.PUSH_PULL) handlePointerMove(e);
                         else handleGlobalMove(e);
                }}
            >
                <mesh rotation={[-Math.PI/2, 0, 0]} position={[0, -0.02, 0]} receiveShadow visible={false}>
                    <planeGeometry args={[1000, 1000]} />
                    <meshBasicMaterial /> 
                </mesh>
            </group>

            {renderShapes.map(shape => (
                <ShapeRenderer 
                    key={shape.id} 
                    shape={shape} 
                    isSelected={selectedIds.includes(shape.id)} 
                    onSelect={(e) => {
                        selectShape(shape.id, e.shiftKey || (tool === ToolType.SELECT && selectedIds.length > 0 && e.metaKey)); 
                    }}
                    pushPullState={ppState}
                    pushPullHandlers={pushPullHandlers}
                    drawingHandlers={drawingHandlers}
                    setDraggingState={setIsObjectDragging}
                />
            ))}

            <InteractionLayer shapes={shapes} tool={tool} setCursorPos={setCursorPos} setSnapInfo={setSnapInfo} cursorPos={cursorPos} snapInfo={snapInfo} drawPoints={drawPoints} isDragging={isDrawing} drawingHeight={drawingHeight} typedInput={typedInput} />

            <SelectionGizmo />

            <OrbitControls makeDefault minDistance={2} maxDistance={50} dampingFactor={0.1} enabled={!isDrawing && !isPPDragging && !isObjectDragging} />
            <GizmoHelper alignment="bottom-right" margin={[80, 80]}>
                <GizmoViewport axisColors={['#ef4444', '#22c55e', '#3b82f6']} labelColor="black" />
            </GizmoHelper>
            <CameraHandler view={view} onFinished={onViewFinished} />
        </>
    );
};

